def reading(s,gs,vs,av,q,f,p,cs,a,g,b):return choose(s,'reading',gs,vs,av,q,fr(f,p),cs,a,g,b)
def vocabulary(s,gs,vs,av,q,cs,a,g,b):return choose(s,'vocabulary',gs,vs,av,q,ru('Выберите реплику, которая сохраняет все условия.'),[fr(f,p) for f,p in cs],a,g,b)

